hl.on("hyprland.start", function ()
  hl.exec_cmd("waybar")
  hl.exec_cmd("swaync")
  -- Wi-Fi 菜单常驻预热（点 waybar 网络图标即开，cairo 渲染约 90MB）
  hl.exec_cmd("/usr/bin/python3 " .. HOME .. "/.local/share/wifi-menu/wifi-menu.py --serve")
  -- hl.exec_cmd("nm-applet")  # 已移除：wifi 图标与菜单由 wifi-menu（GTK4+libnm）替代
  -- 输入法环境变量（fcitx5）：XWayland 应用（Steam/Wine 等）必须靠这些变量接入 fcitx5
  -- 2026-09-02：GTK_IM_MODULE 已停用（注释）——会让 Wayland 原生 GTK 应用（Firefox/Chrome）走 fcitx dbus 前端，候选框整框残影；去掉后走 wayland text-input 协议即正常。XWayland 的 GTK 程序如需要输入法可单独用 env 启动。
  -- hl.env("GTK_IM_MODULE", "fcitx")
  hl.env("QT_IM_MODULE", "fcitx")
  hl.env("XMODIFIERS", "@im=fcitx")
  -- 鼠标指针：Catppuccin Mocha Mauve（2026-11-27 加入；此前一直用 Adwaita 默认箭头，
  -- 那 16 套 catppuccin-cursors 装了但从没启用过）。env 管新启动的程序，
  -- setcursor 管 Hyprland 自己已画的指针 —— 两者都要，缺一个就有一部分界面还是旧箭头。
  hl.env("XCURSOR_THEME", "catppuccin-mocha-mauve-cursors")
  hl.env("HYPRCURSOR_THEME", "catppuccin-mocha-mauve-cursors")
  hl.exec_cmd("hyprctl setcursor catppuccin-mocha-mauve-cursors 24")
  -- fcitx5 由 systemd autostart 统一管理（/etc/xdg/autostart/org.fcitx.Fcitx5.desktop），此处不再重复启动，避免双实例冲突弹窗（2026-08-28）
  -- hl.exec_cmd("fcitx5 -d")
  -- 2026-10-09：原写法命令名不在 PATH（二进制实际在 /usr/lib/polkit-gnome/），静默失败 → 认证代理一直没起来；改为绝对路径（NINA酱）
  hl.exec_cmd("/usr/lib/polkit-gnome/polkit-gnome-authentication-agent-1")
  hl.exec_cmd("cliphist daemon")
  hl.exec_cmd("hypridle")
-- 壁纸引擎（waywallen，视频/动态壁纸）：本仓库不含壁纸，换装之后把这行改成你的壁纸程序。
