-- See https://wiki.hypr.land/Configuring/Basics/Window-Rules/
-- and https://wiki.hypr.land/Configuring/Basics/Workspace-Rules/

-- Example window rules that are useful

local suppressMaximizeRule = hl.window_rule({
    -- Ignore maximize requests from all apps. You'll probably like this.
    name  = "suppress-maximize-events",
    match = { class = ".*" },

    suppress_event = "maximize",
})
-- suppressMaximizeRule:set_enabled(false)

hl.window_rule({
    -- Fix some dragging issues with XWayland
    name  = "fix-xwayland-drags",
    match = {
        class      = "^$",
        title      = "^$",
        xwayland   = true,
        float      = true,
        fullscreen = false,
        pin        = false,
    },

    no_focus = true,
})

-- Layer rules also return a handle.
-- local overlayLayerRule = hl.layer_rule({
--     name  = "no-anim-overlay",
--     match = { namespace = "^my-overlay$" },
--     no_anim = true,
-- })
-- overlayLayerRule:set_enabled(false)

-- waybar 整条栏毛玻璃（2026-10-13）：给栏的 layer surface 加模糊，
-- ignore_alpha 让透明区（岛与岛之间的缝隙）不参与模糊。
hl.layer_rule({
    name         = "waybar-glass",
    match        = { namespace = "waybar" },
    blur         = true,
    ignore_alpha = 0.2,
})

-- Rofi（应用列表 / 剪贴板菜单）与 wlogout（关机菜单）的磨砂
-- HyDE 同款：windowrules 里就是 layerrule = blur,rofi / blur,logout_dialog + ignorezero
hl.layer_rule({
    name         = "rofi-blur",
    match        = { namespace = "rofi" },
    blur         = true,
    ignore_alpha = 0,
})

hl.layer_rule({
    name         = "wlogout-blur",
    match        = { namespace = "logout_dialog" },
    blur         = true,
    ignore_alpha = 0,
    dim_around   = true,   -- 菜单弹出时把周围压暗（强度见 decoration.dim_strength）
})

-- Hyprland-run windowrule
hl.window_rule({
    name  = "move-hyprland-run",
    match = { class = "hyprland-run" },

    move  = "20 monitor_h-120",
    float = true,
})
-- Nemo 透明背景（保持 0.75 半透明，但**不吃**全局模糊）
-- 2026-10-13 加 no_blur：当天为 waybar 毛玻璃把全局 blur 从 3/1 提到 8/3，
-- 强度是全局的，Nemo 跟着变成重磨砂 —— 这里单独关掉，恢复「纯半透明」观感。
hl.window_rule({
    name = "nemo-opacity",
    match = { class = "^nemo$" },
    opacity = 0.75,
    no_blur = true,
})
-- 微信主窗口（标题“微信”）：去掉边框，保留模糊等原生特效
-- 微信主窗口：不设任何特殊规则，继承全局默认样式（紫色边框、模糊等）
-- 删除之前的微信主窗口规则，或者将其注释掉。

-- 微信小窗口：去掉 Hyprland 边框，并强制窗口不画自带的黑线
hl.window_rule({
    match = { class = "^wechat$", title = "^wechat$" },
    no_blur = true,
    border_size = 0,
    no_shadow = true,  
})
-- 百度网盘小窗（悬浮播放/下载悬浮球）：浮动 + 置顶，去边框/阴影/动画
hl.window_rule({
    name = "baidunetdisk-float-top",
    match = { class = "^baidunetdisk$", title = "^baidunetdisk$" },
    float       = true,   -- 不被平铺
    pin         = true,   -- 置顶，所有工作区可见
    border_size = 0,      -- 去边框
    no_shadow   = true,   -- 去阴影
    no_anim     = true,   -- 去动画，防抖动
    no_blur     = true,   -- 去磨砂背景
    opaque      = true,   -- 强制不透明，防透底
})
-- Wallpaper Engine (Proton)：空标题装饰/对话框窗口去边框、不可聚焦、无动画、完全透明不渲染
hl.window_rule({
    name = "we-decor-cleanup",
    match = { class = "^(steam_app_431960)$", title = "^$" },
    border_size = 0,
    no_focus = true,
    no_anim = true,
    opacity = 0,
})
-- 明日方舟（Steam/Proton）：空标题的 160×20 辅助小窗（白色小条）→ 去边框、不可聚焦、无动画、完全透明不渲染
-- 只匹配空标题的辅助窗，不碰「鹰角启动器」主窗
hl.window_rule({
    name = "ark-decor-cleanup",
    match = { class = "^steam_app_2243810413$", title = "^$" },
    border_size = 0,
    no_focus = true,
    no_anim = true,
    opacity = 0,
})
-- ====================================
--  复杂布局（带 gaps）
--  屏幕：1920×1200，Waybar：30px
--  gaps_out=20，gaps_in=5
--  右：雨窗（50%宽 × 100%高）
--  左上：信息窗（50%宽 × 50%高）
--  左中：猫窗（50%宽 × 25%高，cool-retro-term）
--  左下：时钟窗（50%宽 × 25%高）
-- ====================================

-- 信息窗（左上）
hl.window_rule({
    name = "layout-info",
    match = { title = "^info-terminal$" },
    float = true,
    size = { 937, 560 },
    move = { 20, 50 },
})

-- 猫窗（左中，cool-retro-term）
hl.window_rule({
    name = "layout-nyan",
    match = { class = "^cool-retro-term$" },
    float = true,
    size = { 937, 280 },
    move = { 20, 615 },
})

-- 时钟窗（左下）
hl.window_rule({
    name = "layout-clock",
    match = { title = "^clock-terminal$" },
    float = true,
    size = { 937, 280 },
    move = { 20, 900 },
})

-- 雨窗（右侧，全高）
hl.window_rule({
    name = "layout-rain",
    match = { title = "^rain-terminal$" },
    float = true,
    size = { 938, 1130 },
    move = { 962, 50 },
})
-- 保护普通 Ghostty 浮动窗口（如确认对话框）不被意外去边框
hl.window_rule({
    name = "restore-ghostty-dialog-border",
    match = {
        class = "^com.mitchellh.ghostty$",
        float = true,
        title = "negative:^(info|rain|clock)-terminal$"
    },
    border_size = 2,
    rounding = 8,
    no_blur = false,
    no_shadow = false,
})

-- BongoCat 桌宠（XWayland）：去边框/阴影/模糊，悬浮置顶
-- 尺寸控制：改下面 size 的 { 宽, 高 } → hyprctl reload → 重开猫
hl.window_rule({
    name = "bongocat-pet",
    match = { class = "^BongoCat$", title = "^BongoCat$" },
    float = true,
    pin = true,
    border_size = 0,
    rounding = 0,
    no_shadow = true,
    no_blur = true,
    no_anim = true,
    size = { 312, 287 },
    move = { 1580, 842 },
    opacity = 1.0,   -- 窗口不透明度（Hyprland 侧生效；app 自带的 _NET_WM_WINDOW_OPACITY 在 XWayland 下不被兑现）
})

-- BongoCat 偏好设置窗（同一个 class，用 title 区分）：正常浮动，尺寸交还程序自己决定
hl.window_rule({
    name = "bongocat-settings",
    match = { class = "^BongoCat$", title = "^BongoCat - Settings$" },
    float = true,
})

